package cli

import (
 "bytes"
 "os"
 "os/exec"
 "path/filepath"
 "strings"
 "testing"
 posemodel "github.com/harne8/pose-mcp/internal/pose"
)

func TestB38R9IndependentWitnessLoss(t *testing.T) {
 drop := func(t *testing.T, root string) { t.Helper(); for _, p := range []string{".pose/policy/release.json", ".pose/release-policy.json"} { if e := os.Remove(filepath.Join(root,p)); e != nil && !os.IsNotExist(e) { t.Fatal(e) } } }
 rm := func(t *testing.T, p string) { t.Helper(); if e:=os.RemoveAll(p); e!=nil {t.Fatal(e)} }
 for _, name := range []string{"lost-inventory-link", "inventory-is-file", "tag-list-fails", "tag-manifest-blob-lost", "tag-manifest-is-link", "tag-has-policy-but-no-manifest"} {
  t.Run(name,func(t *testing.T) {
   root:=adoptedTaggedRelease(t)
   if c,o:=releaseCheckerFor(root); c.errors!=0 {t.Fatalf("control: %s",o.String())}
   switch name {
   case "lost-inventory-link", "inventory-is-file":
    releaseGit(t,root,"tag","-d","v1.0.0")
    rm(t,filepath.Join(root,".pose/releases"))
    if name=="lost-inventory-link" {if e:=os.Symlink(filepath.Join(root,"lost"),filepath.Join(root,".pose/releases"));e!=nil {t.Fatal(e)}} else {writeReleaseFixture(t,root,".pose/releases","lost inventory")}
   case "tag-list-fails":
    rm(t,filepath.Join(root,".pose/releases"))
    git,e:=exec.LookPath("git");if e!=nil {t.Fatal(e)}
    bin:=t.TempDir(); wrapper:="#!/bin/sh\nfor a in \"$@\"; do if [ \"$a\" = tag ]; then echo injected-tag-read-failure >&2; exit 128; fi; done\nexec '"+git+"' \"$@\"\n"
    if e:=os.WriteFile(filepath.Join(bin,"git"),[]byte(wrapper),0755); e!=nil {t.Fatal(e)}
    t.Setenv("PATH",bin+string(os.PathListSeparator)+os.Getenv("PATH"))
   case "tag-manifest-blob-lost":
    hash:=strings.TrimSpace(gitOut(t,root,"rev-parse","v1.0.0:.pose/releases/v1.0.0/manifest.json"))
    if e:=os.Remove(filepath.Join(root,".git/objects",hash[:2],hash[2:]));e!=nil {t.Fatal(e)}
    rm(t,filepath.Join(root,".pose/releases"))
   case "tag-manifest-is-link":
    releaseGit(t,root,"tag","-d","v1.0.0")
    rm(t,filepath.Join(root,".pose/releases/v1.0.0/manifest.json"))
    if e:=os.Symlink("lost",filepath.Join(root,".pose/releases/v1.0.0/manifest.json"));e!=nil {t.Fatal(e)}
    releaseGit(t,root,"add","-A");releaseGit(t,root,"commit","-q","-m","link instead of manifest");releaseGit(t,root,"tag","v1.0.0")
    rm(t,filepath.Join(root,".pose/releases"))
   case "tag-has-policy-but-no-manifest":
    releaseGit(t,root,"tag","-d","v1.0.0")
    releaseGit(t,root,"rm","-q","-r",".pose/releases")
    releaseGit(t,root,"commit","-q","-m","snapshot missing");releaseGit(t,root,"tag","v1.0.0")
   }
   drop(t,root)
   c,o:=releaseCheckerFor(root)
   status,statusErr:=(posemodel.Store{Root:root}).GetReleaseStatus(""); if status!=nil {for _,r:=range status.Releases {t.Logf("status.version=%s sound=%v gaps=%q",r.Version,r.Sound(),r.Gaps)}}
   gaps,_:=checkRelease(root,"v1.0.0")
   snap,snapErr:=posemodel.ReadReleaseSnapshot(root,"v1.0.0")
   t.Logf("checker.errors=%d output=%q status.error=%v check.gaps=%q snapshot.error=%v snapshot.intact=%v",c.errors,o.String(),statusErr,gaps,snapErr,snap.Intact())
   if c.errors==0 {t.Error("release checker approved after losing the evidence it had to read")}
  })
 }
 t.Run("controls",func(t *testing.T){
  for _,name:=range []string{"intact", "policy-only-lost", "inventory-and-policy-absent-with-intact-tag", "legacy-no-adoption"} {
   t.Run(name,func(t *testing.T){
    root:=adoptedTaggedRelease(t);wantError:=false
    switch name {
    case "policy-only-lost":drop(t,root);wantError=true
    case "inventory-and-policy-absent-with-intact-tag":rm(t,filepath.Join(root,".pose/releases"));drop(t,root);wantError=true
    case "legacy-no-adoption":releaseGit(t,root,"tag","-d","v1.0.0");drop(t,root);rm(t,filepath.Join(root,".pose/releases"));releaseGit(t,root,"add","-A");releaseGit(t,root,"commit","-q","-m","legacy control");releaseGit(t,root,"tag","v1.0.0")
    }
    c,o:=releaseCheckerFor(root);t.Logf("errors=%d output=%q",c.errors,o.String());if (c.errors>0)!=wantError {t.Fatal("control did not behave as expected")}
   })
  }
 })
}

func TestB38R9TempFailureMustNotQualifyWrongVersion(t *testing.T) {
 for _,kind:=range []string{"text","json"} {t.Run(kind,func(t *testing.T){
  root:=adoptedTaggedRelease(t)
  releaseGit(t,root,"tag","-d","v1.0.0")
  if kind=="text" {writeReleaseFixture(t,root,"VERSION","2.0.0\n")} else {
   policy,e:=posemodel.LoadReleasePolicy(root);if e!=nil {t.Fatal(e)}
   policy.VersionSource=&posemodel.ReleaseVersionSource{Path:"package.json",Kind:"json",Key:"version"}
   writeReleaseFixture(t,root,".pose/policy/release.json",string(posemodel.CanonicalJSON(policy)))
   old,e:=posemodel.LoadReleaseManifest(root,"v1.0.0");if e!=nil {t.Fatal(e)}
   m:=posemodel.NewReleaseManifest(old.Version,old.PreviousVersion,old.PreparedAt,old.Fragments,policy,posemodel.LoadChangelogPolicy(root),map[string]string{"source":"package.json","kind":"json","value":"v1.0.0"})
   writeReleaseFixture(t,root,".pose/releases/v1.0.0/manifest.json",string(posemodel.CanonicalJSON(m)))
   writeReleaseFixture(t,root,"package.json",`{"version":"2.0.0"}`)
  }
  releaseGit(t,root,"add","-A");releaseGit(t,root,"commit","-q","-m","version source differs from cut");releaseGit(t,root,"tag","v1.0.0")
  snap,e:=posemodel.ReadReleaseSnapshot(root,"v1.0.0");if e!=nil || snap.Intact(){t.Fatalf("control intact=%v err=%v",snap.Intact(),e)}
  gaps,_:=checkRelease(root,"v1.0.0");if len(gaps)==0 {t.Fatal("wrong-version control was not refused")}
  t.Logf("control gaps=%q",gaps)
  for _,failure:=range []string{"missing-parent","not-a-directory"} {t.Run(failure,func(t *testing.T){
   temp:=filepath.Join(root,failure)
   if failure=="not-a-directory" {writeReleaseFixture(t,root,failure,"file")}
   t.Setenv("TMPDIR",temp)
   snap,e=posemodel.ReadReleaseSnapshot(root,"v1.0.0")
   gaps,_=checkRelease(root,"v1.0.0")
   s,se:=(posemodel.Store{Root:root}).GetReleaseStatus("")
   sound:=se==nil && len(s.Releases)>0 && s.Releases[0].Sound()
   c,o:=releaseCheckerFor(root)
   var out,errOut bytes.Buffer
   code:=cmdReleaseCheck(root,[]string{"--version","v1.0.0","--strict","--json"},&out,&errOut)
   t.Logf("snapshot.intact=%v snapshot.error=%v limits=%q check.gaps=%q status.error=%v status.sound=%v checker.errors=%d output=%q CLI.exit=%d CLI.json=%s CLI.stderr=%s",snap.Intact(),e,snap.Limits,gaps,se,sound,c.errors,o.String(),code,out.String(),errOut.String())
   if snap.Intact() || len(gaps)==0 || sound || c.errors==0 || code==0 {t.Error("I/O failure qualified a release whose version source contradicts the manifest")}
  })}
 })}
}

