package cli
import("testing";"os";"path/filepath")
func TestB38R9UnadoptedCutWitness(t *testing.T){root:=cliReleaseRepo(t);c,o:=releaseCheckerFor(root);if c.errors!=0{t.Fatalf("control %s",o.String())};if e:=os.Remove(filepath.Join(root,".pose/policy/release.json"));e!=nil{t.Fatal(e)};c,o=releaseCheckerFor(root);t.Logf("unadopted cut, lost optional policy: errors=%d output=%q",c.errors,o.String());if c.errors==0{t.Fatal("probe behavior changed")}}
